import{_ as t,a0 as o,w as d,s as r,I as e,x as i,a1 as n,A as p,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"放棄 ifconfig，擁抱 ip 命令 | LCTT x X-CMD","titleTemplate":false,"description":"放棄 ifconfig，擁抱 ip 命令 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"放棄 ifconfig，擁抱 ip 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"放棄 ifconfig，擁抱 ip 命令 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20210125 Why you need to drop ifconfig for ip","title":"放棄 ifconfig，擁抱 ip 命令","tag":"202102","desc":""},"relativePath":"202102/20210125 Why you need to drop ifconfig for ip.md","filePath":"[post].md"}'),c={name:"202102/20210125 Why you need to drop ifconfig for ip.md"};function f(h,s,g,k,u,b){const a=o("Link");return d(),r("div",null,[s[27]||(s[27]=e("h1",{id:"放棄-ifconfig-擁抱-ip-命令",tabindex:"-1"},[i("放棄 ifconfig，擁抱 ip 命令 "),e("a",{class:"header-anchor",href:"#放棄-ifconfig-擁抱-ip-命令","aria-label":"Permalink to “放棄 ifconfig，擁抱 ip 命令”"},"​")],-1)),s[28]||(s[28]=e("blockquote",null,[e("p",null,"開始使用現代方法配置 Linux 網絡接口。")],-1)),s[29]||(s[29]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202102/05/233847lpg1lnz7kl2czgfj.jpg",alt:""})],-1)),s[30]||(s[30]=e("p",null,[i("在很長一段時間內，"),e("code",null,"ifconfig"),i(" 命令是配置網絡接口的默認方法。它為 Linux 用户提供了很好的服務，但是網絡很複雜，所以配置網絡的命令必須健壯。"),e("code",null,"ip"),i(" 命令是現代系統中新的默認網絡命令，在本文中，我將向你展示如何使用它。")],-1)),e("p",null,[s[1]||(s[1]=e("code",null,"ip",-1)),s[2]||(s[2]=i(" 命令工作在 ",-1)),n(a,{href:"https://en.wikipedia.org/wiki/OSI_model"},{default:p(()=>[...s[0]||(s[0]=[i("OSI 網絡棧",-1)])]),_:1}),s[3]||(s[3]=i(" 的兩個層上：第二層（數據鏈路層）和第三層（網絡 或 IP）層。它做了之前 ",-1)),s[4]||(s[4]=e("code",null,"net-tools",-1)),s[5]||(s[5]=i(" 包的所有工作。",-1))]),s[31]||(s[31]=l(`<h3 id="安裝-ip" tabindex="-1">安裝 ip <a class="header-anchor" href="#安裝-ip" aria-label="Permalink to “安裝 ip”">​</a></h3><p><code>ip</code> 命令包含在 <code>iproute2util</code> 包中，它可能已經在你的 Linux 發行版中安裝了。如果沒有，你可以從發行版的倉庫中進行安裝。</p><h3 id="ifconfig-和-ip-使用對比" tabindex="-1">ifconfig 和 ip 使用對比 <a class="header-anchor" href="#ifconfig-和-ip-使用對比" aria-label="Permalink to “ifconfig 和 ip 使用對比”">​</a></h3><p><code>ip</code> 和 <code>ifconfig</code> 命令都可以用來配置網絡接口，但它們做事方法不同。接下來，作為對比，我將用它們來執行一些常見的任務。</p><h4 id="查看網口和-ip-地址" tabindex="-1">查看網口和 IP 地址 <a class="header-anchor" href="#查看網口和-ip-地址" aria-label="Permalink to “查看網口和 IP 地址”">​</a></h4><p>如果你想查看主機的 IP 地址或網絡接口信息，<code>ifconfig</code> （不帶任何參數）命令提供了一個很好的總結。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifconfig</span></span>
<span class="line"><span>                                                                                                </span></span>
<span class="line"><span>eth0: flags=4099&lt;UP,BROADCAST,MULTICAST&gt;  mtu 1500                                                                 </span></span>
<span class="line"><span>       ether bc:ee:7b:5e:7d:d8  txqueuelen 1000  (Ethernet)                                                       </span></span>
<span class="line"><span>       RX packets 0  bytes 0 (0.0 B)</span></span>
<span class="line"><span>       RX errors 0  dropped 0  overruns 0  frame 0</span></span>
<span class="line"><span>       TX packets 0  bytes 0 (0.0 B)</span></span>
<span class="line"><span>       TX errors 0  dropped 0 overruns 0  carrier 0  collisions 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>lo: flags=73&lt;UP,LOOPBACK,RUNNING&gt;  mtu 65536</span></span>
<span class="line"><span>       inet 127.0.0.1  netmask 255.0.0.0</span></span>
<span class="line"><span>       inet6 ::1  prefixlen 128  scopeid 0x10&lt;host&gt;</span></span>
<span class="line"><span>       loop  txqueuelen 1000  (Local Loopback)</span></span>
<span class="line"><span>       RX packets 41  bytes 5551 (5.4 KiB)</span></span>
<span class="line"><span>       RX errors 0  dropped 0  overruns 0  frame 0</span></span>
<span class="line"><span>       TX packets 41  bytes 5551 (5.4 KiB)</span></span>
<span class="line"><span>       TX errors 0  dropped 0 overruns 0  carrier 0  collisions 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>wlan0: flags=4163&lt;UP,BROADCAST,RUNNING,MULTICAST&gt;  mtu 1500</span></span>
<span class="line"><span>       inet 10.1.1.6  netmask 255.255.255.224  broadcast 10.1.1.31</span></span>
<span class="line"><span>       inet6 fdb4:f58e:49f:4900:d46d:146b:b16:7212  prefixlen 64  scopeid 0x0&lt;global&gt;</span></span>
<span class="line"><span>       inet6 fe80::8eb3:4bc0:7cbb:59e8  prefixlen 64  scopeid 0x20&lt;link&gt;</span></span>
<span class="line"><span>       ether 08:71:90:81:1e:b5  txqueuelen 1000  (Ethernet)</span></span>
<span class="line"><span>       RX packets 569459  bytes 779147444 (743.0 MiB)</span></span>
<span class="line"><span>       RX errors 0  dropped 0  overruns 0  frame 0</span></span>
<span class="line"><span>       TX packets 302882  bytes 38131213 (36.3 MiB)</span></span>
<span class="line"><span>       TX errors 0  dropped 0 overruns 0  carrier 0  collisions 0</span></span></code></pre></div><p>新的 <code>ip</code> 命令提供了類似的結果，但命令是 <code>ip address show</code>，或者簡寫為 <code>ip a</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip a</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1: lo: &lt;LOOPBACK,UP,LOWER_UP&gt; mtu 65536 qdisc noqueue state UNKNOWN group default qlen 1000</span></span>
<span class="line"><span>   link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00</span></span>
<span class="line"><span>   inet 127.0.0.1/8 scope host lo</span></span>
<span class="line"><span>      valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>   inet6 ::1/128 scope host  </span></span>
<span class="line"><span>      valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>2: eth0: &lt;NO-CARRIER,BROADCAST,MULTICAST,UP&gt; mtu 1500 qdisc pfifo_fast state DOWN group default qlen 1000</span></span>
<span class="line"><span>   link/ether bc:ee:7b:5e:7d:d8 brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>3: wlan0: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc noqueue state UP group default qlen 1000</span></span>
<span class="line"><span>   link/ether 08:71:90:81:1e:b5 brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>   inet 10.1.1.6/27 brd 10.1.1.31 scope global dynamic wlan0</span></span>
<span class="line"><span>      valid_lft 83490sec preferred_lft 83490sec</span></span>
<span class="line"><span>   inet6 fdb4:f58e:49f:4900:d46d:146b:b16:7212/64 scope global noprefixroute dynamic  </span></span>
<span class="line"><span>      valid_lft 6909sec preferred_lft 3309sec</span></span>
<span class="line"><span>   inet6 fe80::8eb3:4bc0:7cbb:59e8/64 scope link  </span></span>
<span class="line"><span>      valid_lft forever preferred_lft forever</span></span></code></pre></div><h4 id="添加-ip-地址" tabindex="-1">添加 IP 地址 <a class="header-anchor" href="#添加-ip-地址" aria-label="Permalink to “添加 IP 地址”">​</a></h4><p>使用 <code>ifconfig</code> 命令添加 IP 地址命令為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifconfig eth0 add 192.9.203.21</span></span></code></pre></div><p><code>ip</code> 類似：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip address add 192.9.203.21 dev eth0</span></span></code></pre></div><p><code>ip</code> 中的子命令可以縮短，所以下面這個命令同樣有效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip addr add 192.9.203.21 dev eth0</span></span></code></pre></div><p>你甚至可以更短些：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip a add 192.9.203.21 dev eth0</span></span></code></pre></div><h4 id="移除一個-ip-地址" tabindex="-1">移除一個 IP 地址 <a class="header-anchor" href="#移除一個-ip-地址" aria-label="Permalink to “移除一個 IP 地址”">​</a></h4><p>添加 IP 地址與刪除 IP 地址正好相反。</p><p>使用 <code>ifconfig</code>，命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifconfig eth0 del 192.9.203.21</span></span></code></pre></div><p><code>ip</code> 命令的語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip a del 192.9.203.21 dev eth0</span></span></code></pre></div><h4 id="啓用或禁用組播" tabindex="-1">啓用或禁用組播 <a class="header-anchor" href="#啓用或禁用組播" aria-label="Permalink to “啓用或禁用組播”">​</a></h4>`,25)),e("p",null,[s[8]||(s[8]=i("使用 ",-1)),s[9]||(s[9]=e("code",null,"ifconfig",-1)),s[10]||(s[10]=i(" 接口來啓用或禁用 ",-1)),e("ruby",null,[n(a,{href:"https://en.wikipedia.org/wiki/Multicast"},{default:p(()=>[...s[6]||(s[6]=[i("組播",-1)])]),_:1}),s[7]||(s[7]=e("rt",null,"multicast",-1))]),s[11]||(s[11]=i("：",-1))]),s[32]||(s[32]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ifconfig eth0 multicast</span></span></code></pre></div><p>對於 <code>ip</code>，使用 <code>set</code> 子命令與設備（<code>dev</code>）以及一個布爾值和 <code>multicast</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ip link set dev eth0 multicast on</span></span></code></pre></div><h4 id="啓用或禁用網絡" tabindex="-1">啓用或禁用網絡 <a class="header-anchor" href="#啓用或禁用網絡" aria-label="Permalink to “啓用或禁用網絡”">​</a></h4><p>每個系統管理員都熟悉“先關閉，然後打開”這個技巧來解決問題。對於網絡接口來説，即打開或關閉網絡。</p><p><code>ifconfig</code> 命令使用 <code>up</code> 或 <code>down</code> 關鍵字來實現：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ifconfig eth0 up</span></span></code></pre></div><p>或者你可以使用一個專用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ifup eth0</span></span></code></pre></div><p><code>ip</code> 命令使用 <code>set</code> 子命令將網絡設置為 <code>up</code> 或 <code>down</code> 狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ip link set eth0 up</span></span></code></pre></div><h4 id="開啓或關閉地址解析功能-arp" tabindex="-1">開啓或關閉地址解析功能（ARP） <a class="header-anchor" href="#開啓或關閉地址解析功能-arp" aria-label="Permalink to “開啓或關閉地址解析功能（ARP）”">​</a></h4><p>使用 <code>ifconfig</code>，你可以通過聲明它來啓用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ifconfig eth0 arp</span></span></code></pre></div><p>使用 <code>ip</code>，你可以將 <code>arp</code> 屬性設置為 <code>on</code> 或 <code>off</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ip link set dev eth0 arp on</span></span></code></pre></div><h3 id="ip-和-ipconfig-的優缺點" tabindex="-1">ip 和 ipconfig 的優缺點 <a class="header-anchor" href="#ip-和-ipconfig-的優缺點" aria-label="Permalink to “ip 和 ipconfig 的優缺點”">​</a></h3><p><code>ip</code> 命令比 <code>ifconfig</code> 更通用，技術上也更有效，因為它使用的是 <code>Netlink</code> 套接字，而不是 <code>ioctl</code> 系統調用。</p><p><code>ip</code> 命令可能看起來比 <code>ifconfig</code> 更詳細、更復雜，但這是它擁有更多功能的一個原因。一旦你開始使用它，你會了解它的內部邏輯（例如，使用 <code>set</code> 而不是看起來隨意混合的聲明或設置）。</p><p>最後，<code>ifconfig</code> 已經過時了（例如，它缺乏對網絡命名空間的支持），而 <code>ip</code> 是為現代網絡而生的。嘗試並學習它，使用它，你會由衷高興的！</p><hr>',21)),e("p",null,[s[13]||(s[13]=i("via: ",-1)),n(a,{href:"https://opensource.com/article/21/1/ifconfig-ip-linux"},{default:p(()=>[...s[12]||(s[12]=[i("https://opensource.com/article/21/1/ifconfig-ip-linux",-1)])]),_:1})]),e("p",null,[s[18]||(s[18]=i("作者：",-1)),n(a,{href:"https://opensource.com/users/rajabhar"},{default:p(()=>[...s[14]||(s[14]=[i("Rajan Bhardwaj",-1)])]),_:1}),s[19]||(s[19]=i(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[15]||(s[15]=[i("lujun9972",-1)])]),_:1}),s[20]||(s[20]=i(" 譯者：",-1)),n(a,{href:"https://github.com/MjSeven"},{default:p(()=>[...s[16]||(s[16]=[i("MjSeven",-1)])]),_:1}),s[21]||(s[21]=i(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[17]||(s[17]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[24]||(s[24]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[22]||(s[22]=[i("LCTT",-1)])]),_:1}),s[25]||(s[25]=i(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:p(()=>[...s[23]||(s[23]=[i("Linux中國",-1)])]),_:1}),s[26]||(s[26]=i(" 榮譽推出",-1))])])}const C=t(c,[["render",f]]);export{v as __pageData,C as default};
